BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('stats17-q01', '標本調査法',
   '全国の有権者1億人から3000人を無作為抽出で世論調査したい。名簿の全員に番号をふり、コンピュータでランダムに3000個選ぶ「単純無作為抽出」は理論上もっとも公平な方法だが、実務ではこれだけでは工夫が足りないと言われることがある。その理由として最も適切なのはどれ？',
   NULL::text,
   '["たまたま選ばれた3000人が地域や年代に偏ることがあり、全国民の名簿をそろえて訪問する手間も大きいから", "コンピュータでくじ引きをすれば、選ばれる3000人の地域や年代の構成は必ず母集団と完全に一致するので、工夫は不要である", "単純無作為抽出はそもそも1万人を超えるような大人数の母集団には使うことができない手法だから", "3000人という標本の大きさ自体が、世論調査に使うにはそもそも少なすぎるから"]',
   0, '[0]', 'single',
   '{"asked": "単純無作為抽出という公平な方法があるのに、実務でさらに工夫が必要になる理由は何か。", "point": "無作為に選んでも「たまたま偏る」運の要素は消せない。母集団の構造(地域・年代など)が分かっているなら、それを活かした抽出設計のほうが安定し、コストも抑えやすい。", "kid": "くじ引きで選ぶこと自体はとても公平。でも公平なくじ引きでも、たまたま同じ地域の人ばかり当たってしまうことはある。それに1億人ぶんの名簿をそろえて連絡するのも大変な作業。運まかせと大変さの両方をなんとかしたいので、この先で工夫のある抽出法を学ぶ。", "eg": "クラス40人からくじで5人選ぶとき、くじは公平でも、たまたま男子ばかり5人になることがある。人数が少ないほど、こういう偏りは起こりやすい。", "viz": "<svg viewBox=\"0 0 340 132\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">同じ人数を無作為に選んでも、偏り方は毎回違う</text><rect x=\"20\" y=\"32\" width=\"70\" height=\"64\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"93\" y=\"32\" width=\"70\" height=\"64\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"166\" y=\"32\" width=\"70\" height=\"64\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"239\" y=\"32\" width=\"70\" height=\"64\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"55\" y=\"28\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">地域A</text><text x=\"128\" y=\"28\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">地域B</text><text x=\"201\" y=\"28\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">地域C</text><text x=\"274\" y=\"28\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">地域D</text><circle cx=\"38\" cy=\"50\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"55\" cy=\"50\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"72\" cy=\"50\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"38\" cy=\"66\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"55\" cy=\"66\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"72\" cy=\"66\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"38\" cy=\"82\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"111\" cy=\"58\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"183\" cy=\"58\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"200\" cy=\"58\" r=\"4\" fill=\"#3b82f6\"/><text x=\"55\" y=\"108\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">7人</text><text x=\"128\" y=\"108\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">1人</text><text x=\"201\" y=\"108\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">2人</text><text x=\"274\" y=\"108\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">0人</text><text x=\"170\" y=\"124\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">無作為でも、少ない標本ほど偏りが起きやすい</text></svg>", "terms": [["単純無作為抽出", "母集団の全員に等しい確率を与え、グループ分けをせずにくじ引きのように選ぶ、もっとも基本的な抽出法"], ["標本調査", "母集団の一部だけを選んで調べ、そこから全体の姿を推測する調べ方。既に学んだ全数調査との対比"]], "think": "なぜ「公平なくじ引き」だけでは足りないのかがカギ。無作為抽出は選ばれる確率をみんな平等にするだけで、選ばれた結果の構成まで平等にする保証はない。たまたま同じ地域の人ばかり当たることもある。さらに、母集団が1億人のように大きいと、名簿をそろえて連絡するだけでも膨大な手間とコストがかかる。母集団の地域や年代といった構造をあらかじめ知っているなら、それを無視して運まかせにするより、構造を使って選び方を工夫したほうが、結果が安定しやすく、手間も減らせる。", "vs": "「無作為に選ぶこと」と「選ばれた結果が母集団の縮図になっていること」は別の話。無作為はやり方が公平という意味で、縮図になっているかどうかは、たまたまの運に左右される。", "why_asked": "ここから先で学ぶ層化抽出法・クラスター抽出法・系統抽出法・多段抽出法は、どれも「単純無作為抽出だけでは足りない部分」を補うために考え出された。まずこの限界を理解していないと、それぞれの工夫が何のためにあるのか分からなくなる。", "usecase": "全国規模の世論調査や大規模なアンケートなど、母集団が大きく、かつ地域や年代のような構造がはっきりしている調査で、単純無作為抽出のままでよいかを検討する場面で登場する考え方。", "opt": ["正解。たまたまの偏りが起こりうることと、大人数を対象にする手間・コストの大きさの両方が、単純無作為抽出だけでは足りないと言われる理由になる。", "無作為に選んでも、結果の構成が母集団と完全に一致する保証はない。たまたま偏ることは起こりうる。", "単純無作為抽出は理論上どんな大きさの母集団にも定義できる手法であり、1万人を超えると使えなくなるわけではない。", "標本の大きさが足りるかどうかは別の論点(この先で学ぶ標本サイズの決め方)であり、ここで問題にしている偏りやコストの話とは別。"]}'),

  ('stats17-q02', '標本調査法',
   'ある企業が全社員1200人にアンケートを取りたいが、時間の都合で300人だけに絞りたい。まず社員を「20代」「30代」「40代」「50代以上」の4グループに分け、各グループの人数比に合わせてそれぞれのグループから無作為に選ぶことにした。この抽出方法を何と呼ぶ？',
   NULL::text,
   '["層化抽出法（母集団を性質の近いグループ=層に分け、各層ごとに無作為抽出する方法）", "クラスター抽出法（母集団をいくつかの塊=クラスターに分け、選ばれた塊は丸ごと調べる方法）", "系統抽出法（名簿に等間隔で番号を振り、一定の間隔で抽出する方法）", "単純無作為抽出法（グループ分けをせずに、母集団全員から無作為に選ぶ方法）"]',
   0, '[0]', 'single',
   '{"asked": "性質の近いグループにあらかじめ分けてから、各グループごとに無作為抽出する方法の名前。", "point": "先にグループ(層)へ分け、それぞれの層の中で無作為抽出する。「先に分ける、それから層ごとに選ぶ」の2段構えが層化抽出法の形。", "kid": "層化抽出法は、社員を年代のような似た者どうしのグループに先に分けておいてから、それぞれのグループの中でくじ引きするやり方。グループ分けを最初にやるのがポイント。", "eg": "クラス40人を「窓側の列」「廊下側の列」のように先にグループ分けしてから、それぞれの列でくじを引いて代表を選ぶようなもの。列(グループ)ごとに必ず代表が出るようにできる。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">先に層(年代)へ分け、層ごとに無作為に選ぶ</text><rect x=\"30\" y=\"26\" width=\"280\" height=\"22\" fill=\"#2a2f3f\"/><text x=\"40\" y=\"41\" fill=\"#8892a4\" font-size=\"9\">20代</text><circle cx=\"90\" cy=\"37\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"140\" cy=\"37\" r=\"4\" fill=\"#2a2f3f\" stroke=\"#8892a4\"/><circle cx=\"190\" cy=\"37\" r=\"4\" fill=\"#2a2f3f\" stroke=\"#8892a4\"/><circle cx=\"240\" cy=\"37\" r=\"4\" fill=\"#3b82f6\"/><rect x=\"30\" y=\"52\" width=\"280\" height=\"22\" fill=\"#2a2f3f\" opacity=\"0.7\"/><text x=\"40\" y=\"67\" fill=\"#8892a4\" font-size=\"9\">30代</text><circle cx=\"100\" cy=\"63\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"160\" cy=\"63\" r=\"4\" fill=\"#2a2f3f\" stroke=\"#8892a4\"/><circle cx=\"220\" cy=\"63\" r=\"4\" fill=\"#3b82f6\"/><rect x=\"30\" y=\"78\" width=\"280\" height=\"22\" fill=\"#2a2f3f\"/><text x=\"40\" y=\"93\" fill=\"#8892a4\" font-size=\"9\">40代</text><circle cx=\"110\" cy=\"89\" r=\"4\" fill=\"#3b82f6\"/><circle cx=\"200\" cy=\"89\" r=\"4\" fill=\"#2a2f3f\" stroke=\"#8892a4\"/><rect x=\"30\" y=\"104\" width=\"280\" height=\"22\" fill=\"#2a2f3f\" opacity=\"0.7\"/><text x=\"25\" y=\"119\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"start\">50代〜</text><circle cx=\"110\" cy=\"115\" r=\"4\" fill=\"#3b82f6\"/><text x=\"170\" y=\"134\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">青い点＝各層から無作為に選ばれた人</text></svg>", "terms": [["層", "母集団を分けた、性質の近い人どうしのグループ。ここでは年代の区分"], ["層化抽出法", "母集団をあらかじめ層に分けてから、各層ごとに無作為抽出する方法"]], "think": "なぜ「先に分けてから選ぶ」という2段構えが要るのかがカギ。単純無作為抽出のように1200人全員をひとまとめにしてくじを引くと、たまたま20代ばかり選ばれてしまうこともありうる。先に年代という層に分けておけば、それぞれの層から選ぶことになるので、どの年代からも必ず選ばれる仕組みになる。", "vs": "単純無作為抽出との違いは「先にグループ分けをするかどうか」。層化抽出法は分けてから層ごとに選ぶが、単純無作為抽出はグループ分けをせず全員をまとめて選ぶ。", "why_asked": "層化抽出法は、この先に出てくるクラスター抽出法と並んで、実務でもっともよく使われる工夫の1つ。まず「層」という言葉と「先に分けてから層ごとに選ぶ」という形を正確に押さえておく必要がある。", "usecase": "年代・性別・地域・都市規模など、あらかじめ分かっている属性ごとの意見や実態を取りこぼしなく反映させたいアンケートや世論調査で使われる。", "opt": ["正解。年代という層にあらかじめ分けてから、各層の中で無作為に選んでいるので層化抽出法にあたる。", "クラスター抽出法は選ばれた塊を丸ごと全部調べる方法。今回は各層から一部だけを選んでおり、層を丸ごと調べているわけではない。", "系統抽出法は名簿に等間隔で番号を振って一定間隔で選ぶ方法。年代というグループ分けは行われていない。", "単純無作為抽出法はグループ分けをせずに全員から選ぶ方法。今回は先に年代で分けているので、単純無作為抽出ではない。"]}'),

  ('stats17-q03', '標本調査法',
   '先ほどの企業アンケートで、社員1200人全員から一気に300人を選ぶ単純無作為抽出ではなく、年代ごとに層化抽出(各層から人数比通りに選ぶ)を行うことの利点は何か？',
   NULL::text,
   '["各年代の意見を取りこぼさずに反映でき、単純な無作為抽出よりも推定の精度が上がりやすい", "層ごとに選ぶ人数を変えることは一切できないため、常にすべての層が同じ人数になる", "層に分けた時点で調査そのものが完了しており、その後の無作為抽出という工程が不要になる", "層化抽出法を使うと、選ばれた社員が回答を拒否する心配が自動的になくなる"]',
   0, '[0]', 'single',
   '{"asked": "単純無作為抽出ではなく層化抽出法を使うことの利点は何か。", "point": "層ごとに必ず代表が選ばれるので、各層の特徴を取りこぼしにくく、単純無作為抽出よりも推定のブレが小さくなりやすい。", "kid": "層化抽出法を使うと、20代も30代も40代も50代以上も、必ずそれぞれ何人かは選ばれる。運まかせの単純な無作為抽出だと、たまたまある年代がほとんど選ばれないこともあるが、層化抽出法ではそれが起きにくい。", "eg": "クラス40人からくじで5人選ぶとき、単純にくじを引くと男子ばかり5人になることもある。先に男女で分けてから男女それぞれでくじを引けば、必ず男女どちらからも選ばれる。同じことが年代の層でも起きる。", "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">推定値のブレの大きさを比べる</text><line x1=\"170\" y1=\"30\" x2=\"170\" y2=\"92\" stroke=\"#6ab08d\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\"/><text x=\"170\" y=\"26\" fill=\"#6ab08d\" font-size=\"8.5\" text-anchor=\"middle\">真の値</text><text x=\"90\" y=\"48\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">単純無作為抽出</text><line x1=\"55\" y1=\"62\" x2=\"125\" y2=\"62\" stroke=\"#c9a04a\" stroke-width=\"5\"/><text x=\"90\" y=\"78\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">推定値のばらつきが広い</text><text x=\"255\" y=\"48\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">層化抽出法</text><line x1=\"235\" y1=\"62\" x2=\"275\" y2=\"62\" stroke=\"#3b82f6\" stroke-width=\"5\"/><text x=\"255\" y=\"78\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">推定値のばらつきが狭い</text><text x=\"170\" y=\"104\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">層ごとに必ず選ぶ分、真の値のまわりに</text><text x=\"170\" y=\"118\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">集まりやすい＝精度が上がりやすい</text></svg>", "terms": [["推定の精度", "標本から求めた値が、母集団の本当の値からどれくらいブレずに済むか"], ["層化抽出法", "母集団をあらかじめ層に分けてから、各層ごとに無作為抽出する方法。既に学んだ用語"]], "think": "なぜ層化抽出法のほうが推定の精度が上がりやすいのかがカギ。単純無作為抽出は運まかせなので、たまたまある年代に偏った標本になることがあり、そのときの推定値は真の値から大きくズレやすい。層化抽出法は各層から必ず選ぶので、どの回でも各年代の意見が反映され、標本全体の構成が母集団の構成に近づきやすい。構成が近いほど、そこから計算した推定値も母集団の本当の値に近づきやすくなる。", "vs": "「各層から必ず選ばれる」ことと「回答してくれる」ことは別の話。層化抽出法は選び方の工夫であり、選ばれた人が実際に回答してくれるかどうか(回収率)はまた別の問題として、この先の項目で扱う。", "why_asked": "層化抽出法がなぜわざわざ使われるのか、その動機を理解していないと、単なる手間の多い抽出法にしか見えなくなる。「取りこぼしを防ぎ、精度を上げるため」という目的を押さえておく。", "usecase": "都道府県ごとの意見の違いが大きいと予想される全国調査や、年代によって回答傾向がはっきり異なるとわかっているアンケートで、層化抽出法が選ばれる。", "opt": ["正解。各層から必ず選ぶことで年代の取りこぼしを防ぎ、母集団の構成に近い標本になりやすいぶん、推定の精度も上がりやすい。", "層ごとに選ぶ人数は、母集団の人数比に合わせて変えるのが普通で、常に同じ人数にしなければならないという決まりはない。", "層に分けるのは調査の準備段階であり、そのあとに層ごとで無作為抽出を行う工程が必要。層分けだけで調査が完了するわけではない。", "層化抽出法は選び方の工夫であり、選ばれた人が回答してくれるかどうかとは別の問題。回答の拒否が自動的になくなるわけではない。"]}'),

  ('stats17-q04', '標本調査法',
   '全国1000万世帯の郵便配達の実態を調べたいが、対象世帯を無作為に選んで1軒ずつ全国を訪問するのは大変だ。そこで、全国から50個の「地区」をまず無作為に選び、選ばれた地区の中は世帯を絞らずに全戸を調べることにした。この抽出方法を何と呼ぶ？',
   NULL::text,
   '["クラスター抽出法（母集団をいくつかの塊=クラスターに分け、選ばれた塊は丸ごと調べる方法）", "層化抽出法（母集団をあらかじめ性質の近いグループ=層に分けてから、各層ごとに無作為抽出する方法）", "系統抽出法（名簿に等間隔で番号を振り、一定の間隔で抽出する方法）", "多段抽出法（大きい単位から小さい単位へ、段階的に抽出範囲を絞り込んでいく方法）"]',
   0, '[0]', 'single',
   '{"asked": "母集団をいくつかの塊に分け、選ばれた塊だけを丸ごと全部調べる抽出方法の名前。", "point": "クラスター抽出法は「塊を選ぶ→選ばれた塊は全部調べる」という形。塊の中をさらに絞り込むことはしない。", "kid": "クラスター抽出法は、地区という塊をまずくじで選び、選ばれた地区は住んでいる世帯を全部調べるやり方。選ばれなかった地区はまったく調べない。", "eg": "学校のクラスをいくつか無作為に選び、選ばれたクラスの生徒は全員テストを受けてもらう、というやり方に近い。選ばれなかったクラスはテストを受けない。", "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">地区(塊)を選び、選ばれた地区は丸ごと調べる</text><rect x=\"25\" y=\"28\" width=\"58\" height=\"44\" fill=\"#3b82f6\"/><text x=\"54\" y=\"54\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">地区1</text><text x=\"54\" y=\"66\" fill=\"#e8eaf0\" font-size=\"7.5\" text-anchor=\"middle\">全戸調査</text><rect x=\"93\" y=\"28\" width=\"58\" height=\"44\" fill=\"#2a2f3f\"/><text x=\"122\" y=\"54\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">地区2</text><rect x=\"161\" y=\"28\" width=\"58\" height=\"44\" fill=\"#3b82f6\"/><text x=\"190\" y=\"54\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">地区3</text><text x=\"190\" y=\"66\" fill=\"#e8eaf0\" font-size=\"7.5\" text-anchor=\"middle\">全戸調査</text><rect x=\"229\" y=\"28\" width=\"58\" height=\"44\" fill=\"#2a2f3f\"/><text x=\"258\" y=\"54\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">地区4</text><rect x=\"25\" y=\"80\" width=\"58\" height=\"44\" fill=\"#2a2f3f\"/><text x=\"54\" y=\"106\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">地区5</text><rect x=\"93\" y=\"80\" width=\"58\" height=\"44\" fill=\"#2a2f3f\"/><text x=\"122\" y=\"106\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">地区6</text><rect x=\"161\" y=\"80\" width=\"58\" height=\"44\" fill=\"#2a2f3f\"/><text x=\"190\" y=\"106\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">地区7</text><rect x=\"229\" y=\"80\" width=\"58\" height=\"44\" fill=\"#3b82f6\"/><text x=\"258\" y=\"106\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">地区8</text><text x=\"258\" y=\"118\" fill=\"#e8eaf0\" font-size=\"7.5\" text-anchor=\"middle\">全戸調査</text><text x=\"170\" y=\"132\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">選ばれなかった地区は今回まったく調べない</text></svg>", "terms": [["クラスター", "母集団を分けた塊。選ばれた塊は中身を絞らず丸ごと調べる"], ["クラスター抽出法", "母集団をいくつかのクラスターに分け、選ばれたクラスターは丸ごと調べる方法"]], "think": "なぜ「選ばれた塊を丸ごと調べる」というやり方が役に立つのかがカギ。全国1000万世帯からばらばらに世帯を選ぶと、選ばれた世帯が全国に散らばってしまい、1軒ずつ訪問する移動の手間が膨大になる。地区という塊ごと選んで、その地区の中は全部まとめて調べれば、調査員は選ばれた50地区だけを回ればよく、移動の手間を大きく減らせる。範囲を丸ごと調べられる場所に絞り込むことで、コストを下げるのがクラスター抽出法のねらい。", "vs": "層化抽出法は「すべての層から少しずつ選ぶ」のに対し、クラスター抽出法は「選ばれた塊だけを丸ごと全部調べ、選ばれなかった塊は調べない」。この違いは次の設問で詳しく比べる。", "why_asked": "クラスター抽出法は、訪問調査のようにコストや移動距離が大きな問題になる大規模調査で頻繁に使われる。層化抽出法との違いを混同しやすいので、まず単独での定義を正確に押さえる。", "usecase": "全国規模の訪問調査、世帯調査、学校を単位にした学力調査など、対象を地理的・組織的な塊としてまとめて調べたほうが効率のよい調査で使われる。", "opt": ["正解。地区という塊をまず無作為に選び、選ばれた地区は世帯を絞らず全戸調べているので、クラスター抽出法にあたる。", "層化抽出法は各層から少しずつ選ぶ方法。今回は選ばれた地区を丸ごと全部調べており、一部だけを選んでいるわけではない。", "系統抽出法は名簿に等間隔で番号を振って一定間隔で選ぶ方法。地区という塊のくじ引きとは仕組みが異なる。", "多段抽出法は大きい単位から小さい単位へ段階的に絞り込む方法。今回は地区を選んだあと、その中をさらに絞り込まず全戸調べているので、段階を踏んで絞り込む多段抽出法とは違う。"]}'),

  ('stats17-q05', '標本調査法',
   '層化抽出法とクラスター抽出法は、どちらも母集団をグループに分けてから調べる点は同じだが、実際に標本を選ぶ段階でのやり方が違う。その違いとして正しいのはどれ？',
   NULL::text,
   '["層化抽出法は分けた層それぞれから少しずつ選ぶが、クラスター抽出法は選ばれた塊だけを丸ごと全部調べる", "層化抽出法は選ばれた層だけを丸ごと全部調べるが、クラスター抽出法は分けた塊それぞれから少しずつ選ぶ", "層化抽出法もクラスター抽出法も、どちらも分けたグループのうち選ばれたグループだけを丸ごと全部調べる", "層化抽出法もクラスター抽出法も、どちらも分けたグループそれぞれから少しずつ選ぶという同じやり方をする"]',
   0, '[0]', 'single',
   '{"asked": "層化抽出法とクラスター抽出法は、標本を選ぶ段階で具体的に何が違うのか。", "point": "層化抽出法は「すべての層から少しずつ」、クラスター抽出法は「選ばれた塊だけを丸ごと」。全部のグループに手をつけるか、一部のグループだけに絞るかが分かれ目。", "kid": "層化抽出法は、分けたグループぜんぶから少しずつ人を選ぶ。クラスター抽出法は、分けた塊のうち選ばれたいくつかだけを、丸ごと全部調べる。「全グループから少しずつ」か「一部のグループを丸ごと」かの違い。", "eg": "学年全体を調べたいとき、層化抽出法は「どのクラスからも数人ずつ選ぶ」やり方。クラスター抽出法は「いくつかのクラスを選んで、そのクラスの生徒は全員調べる」やり方。同じ学年を対象にしても、選び方の形がまったく違う。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"85\" y=\"16\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">層化抽出法</text><rect x=\"25\" y=\"26\" width=\"120\" height=\"18\" fill=\"#2a2f3f\"/><circle cx=\"55\" cy=\"35\" r=\"3.5\" fill=\"#3b82f6\"/><circle cx=\"115\" cy=\"35\" r=\"3.5\" fill=\"#3b82f6\"/><rect x=\"25\" y=\"48\" width=\"120\" height=\"18\" fill=\"#2a2f3f\" opacity=\"0.7\"/><circle cx=\"70\" cy=\"57\" r=\"3.5\" fill=\"#3b82f6\"/><rect x=\"25\" y=\"70\" width=\"120\" height=\"18\" fill=\"#2a2f3f\"/><circle cx=\"50\" cy=\"79\" r=\"3.5\" fill=\"#3b82f6\"/><circle cx=\"130\" cy=\"79\" r=\"3.5\" fill=\"#3b82f6\"/><text x=\"85\" y=\"102\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">全部の層から少しずつ選ぶ</text><line x1=\"170\" y1=\"10\" x2=\"170\" y2=\"120\" stroke=\"#2a2f3f\"/><text x=\"255\" y=\"16\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">クラスター抽出法</text><rect x=\"195\" y=\"26\" width=\"120\" height=\"18\" fill=\"#3b82f6\"/><text x=\"255\" y=\"39\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">丸ごと調べる</text><rect x=\"195\" y=\"48\" width=\"120\" height=\"18\" fill=\"#2a2f3f\" opacity=\"0.4\"/><rect x=\"195\" y=\"70\" width=\"120\" height=\"18\" fill=\"#2a2f3f\" opacity=\"0.4\"/><text x=\"255\" y=\"102\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">選ばれた塊だけ丸ごと、他は調べない</text><text x=\"170\" y=\"132\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">「全部から少しずつ」か「一部を丸ごと」か</text></svg>", "terms": [["層", "層化抽出法で分ける、性質の近いグループ。すべての層から選ぶ"], ["クラスター", "クラスター抽出法で分ける塊。選ばれた塊だけを丸ごと調べる"]], "think": "なぜこの2つを混同しやすいのかがカギ。どちらも「母集団を先にグループへ分ける」という準備の仕方は同じなので、そこだけ見ると似ている。違いはその後で、層化抽出法は分けたグループの全部に対して「少しずつ選ぶ」という手をつけるのに対し、クラスター抽出法は分けた塊のうち一部だけを「選んで丸ごと」という形をとり、選ばれなかった塊にはまったく手をつけない。全グループに関わるか、一部のグループだけに絞るかが決定的な違いになる。", "vs": "「グループに分ける」という準備段階が同じなので名前も似た印象を持ちやすいが、目的も逆の関係にある。層化抽出法は取りこぼしを防ぐために全層に関わり、クラスター抽出法は手間を減らすために一部の塊だけに絞る。", "why_asked": "この2つの違いを取り違えると、なぜ層化抽出法は精度が上がりやすく、クラスター抽出法はコストを下げやすいのか、という前の設問までの理解がつながらなくなる。実務でも「どちらを使うべきか」を判断する場面が多い。", "usecase": "調査の設計段階で「取りこぼしを防ぐ精度」を優先するなら層化抽出法、「訪問の手間やコスト」を優先するならクラスター抽出法、というように目的に応じて選び分ける。", "opt": ["正解。層化抽出法は全部の層から少しずつ選び、クラスター抽出法は選ばれた塊だけを丸ごと全部調べる。全グループに関わるか一部に絞るかが違い。", "層化抽出法とクラスター抽出法の説明が入れ替わっている。全部を丸ごと調べるのはクラスター抽出法、少しずつ選ぶのは層化抽出法。", "全部のグループを丸ごと全部調べてしまっては、標本調査ではなく全数調査に近づいてしまう。クラスター抽出法でも選ばれなかった塊は調べない。", "層化抽出法は全部の層から少しずつ選ぶが、クラスター抽出法は選ばれた塊を丸ごと調べる方法であり、同じやり方をしているわけではない。"]}'),

  ('stats17-q06', '標本調査法',
   '会員名簿10000人に1番から10000番まで番号がふってある。まず1〜20の中からくじで1つ(たとえば7番)を選び、そこから20人おきに27番、47番、67番…と機械的に選んでいき、合わせて500人の標本を作った。この抽出方法を何と呼ぶ？',
   NULL::text,
   '["系統抽出法（名簿に等間隔で番号を振り、一定の間隔で抽出する方法）", "層化抽出法（母集団をあらかじめ性質の近いグループ=層に分けてから、各層ごとに無作為抽出する方法）", "クラスター抽出法（母集団をいくつかの塊=クラスターに分け、選ばれた塊は丸ごと調べる方法）", "多段抽出法（大きい単位から小さい単位へ、段階的に抽出範囲を絞り込んでいく方法）"]',
   0, '[0]', 'single',
   '{"asked": "名簿の最初だけをくじで決め、そこから先は等間隔に機械的に選んでいく抽出方法の名前。", "point": "最初の1人だけをくじで決め、あとは名簿の番号順に一定の間隔(今回は20人おき)で機械的に選んでいく。これが系統抽出法の形。", "kid": "系統抽出法は、名簿の最初のほうでくじを1回引いたら、あとは同じ間隔でずっと機械的に選んでいくやり方。1回くじを引くだけで、残りは番号を数えるだけで済む。", "eg": "名簿の並びを歩道に見立てると、最初にどこから歩き出すかだけをくじで決め、あとは「20歩ごとに立ち止まって印をつける」を名簿の最後まで機械的に繰り返すようなもの。", "viz": "<svg viewBox=\"0 0 340 132\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">最初の1人だけくじ、あとは20人おきに機械的に選ぶ</text><line x1=\"20\" y1=\"64\" x2=\"320\" y2=\"64\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><circle cx=\"20\" cy=\"64\" r=\"3\" fill=\"#2a2f3f\"/><circle cx=\"320\" cy=\"64\" r=\"3\" fill=\"#2a2f3f\"/><text x=\"20\" y=\"80\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">1番</text><text x=\"320\" y=\"80\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">10000番</text><circle cx=\"41\" cy=\"64\" r=\"5\" fill=\"#c9a04a\"/><text x=\"41\" y=\"46\" fill=\"#c9a04a\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">7番(くじ)</text><circle cx=\"101\" cy=\"64\" r=\"5\" fill=\"#3b82f6\"/><text x=\"101\" y=\"80\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">27番</text><circle cx=\"161\" cy=\"64\" r=\"5\" fill=\"#3b82f6\"/><text x=\"161\" y=\"80\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">47番</text><circle cx=\"221\" cy=\"64\" r=\"5\" fill=\"#3b82f6\"/><text x=\"221\" y=\"80\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">67番</text><circle cx=\"281\" cy=\"64\" r=\"5\" fill=\"#3b82f6\"/><text x=\"281\" y=\"80\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">87番</text><text x=\"170\" y=\"104\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">くじは最初の1回だけ。あとは常に+20番おき</text><text x=\"170\" y=\"120\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">10000÷500=20人おきに機械的に選ぶ</text></svg>", "terms": [["抽出間隔", "系統抽出法で何人おきに選ぶかを表す数。ここでは10000人÷500人=20人おき"], ["系統抽出法", "名簿に等間隔で番号を振り、一定の間隔で抽出する方法"]], "think": "なぜ最初の1回だけくじを引けば済むのかがカギ。名簿の並び順そのものに、選ぶ人を偏らせるような特別な規則性がなければ、最初の出発点さえランダムに決めておけば、そこから等間隔に選んでいく先の499人も、実質的にランダムに選んだのとほぼ同じ結果になる。層化抽出法やクラスター抽出法のように前もってグループ分けをする手間がなく、名簿さえあれば準備がとても簡単なのが系統抽出法の特徴。", "vs": "層化抽出法やクラスター抽出法は「先にグループへ分ける」作業が要るが、系統抽出法はグループ分けをせず、名簿の並び順と間隔だけで機械的に選ぶ。準備の手軽さが際立った方法。", "why_asked": "系統抽出法は名簿さえあればすぐ実行できる手軽さが評価される一方、名簿の並び方そのものに周期的な偏りがあると、機械的な間隔と噛み合って偏った標本になる落とし穴もある(たとえば名簿が10人ずつのグループ順に並んでいて間隔が10の倍数だと、いつも同じ立場の人ばかり選ばれてしまう)。手軽さと、この落とし穴の両方を知っておく必要がある。", "usecase": "会員名簿や卒業生名簿のように、すでに整った名簿がある場合に、手早く標本を作りたいときに使われる。", "opt": ["正解。最初の1人だけをくじで決め、そこから20人おきに機械的に選んでいるので系統抽出法にあたる。", "層化抽出法は先に性質の近いグループへ分けてから、各グループの中でさらに無作為に選ぶ方法。今回は年代などのグループ分けを行っていない。", "クラスター抽出法は塊を選んで丸ごと調べる方法。今回は10000人の名簿から1人ずつ間隔をあけて選んでおり、塊ごと調べているわけではない。", "多段抽出法は大きい単位から小さい単位へ段階を踏んで絞り込む方法。今回は名簿から直接、間隔をあけて選ぶ1段階の手順で完結している。"]}'),

  ('stats17-q07', '標本調査法',
   '全国の中学生の学力調査をしたい。まず全国から市区町村をいくつか無作為に選び、次に選ばれた市区町村の中から学校をいくつか無作為に選び、さらに選ばれた学校の中から生徒を無作為に選ぶ、というように段階を踏んで絞り込んだ。この抽出方法を何と呼ぶ？',
   NULL::text,
   '["多段抽出法（大きい単位から小さい単位へ、段階的に抽出範囲を絞り込んでいく方法）", "クラスター抽出法（母集団をいくつかの塊=クラスターに分け、選ばれた塊は丸ごと調べる方法）", "層化抽出法（母集団をあらかじめ性質の近いグループ=層に分けてから、各層ごとに無作為抽出する方法）", "系統抽出法（名簿に等間隔で番号を振り、一定の間隔で抽出する方法）"]',
   0, '[0]', 'single',
   '{"asked": "市区町村→学校→生徒のように、大きい単位から小さい単位へ段階を踏んで絞り込む抽出方法の名前。", "point": "「大きい単位を選ぶ→その中でさらに小さい単位を選ぶ」を繰り返すのが多段抽出法。段階が複数あることが決め手。", "kid": "多段抽出法は、まず市区町村という大きい単位を選び、その中から学校という少し小さい単位を選び、さらにその中から生徒という一人ひとりを選ぶというように、範囲を何段階にもわたって絞り込んでいくやり方。", "eg": "お土産探しの手順に近い。まず「どの都道府県に行くか」を決め、次に「その中のどのお店に入るか」を決め、最後に「その店のどの商品を買うか」を決める。大きい範囲から少しずつ絞り込んでいく。", "viz": "<svg viewBox=\"0 0 340 132\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">大きい単位から小さい単位へ、段階的に絞り込む</text><rect x=\"20\" y=\"28\" width=\"80\" height=\"28\" fill=\"#3b82f6\"/><text x=\"60\" y=\"46\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">全国の市区町村</text><line x1=\"100\" y1=\"42\" x2=\"128\" y2=\"42\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><polygon points=\"132,42 126,38.5 126,45.5\" fill=\"#8892a4\"/><rect x=\"135\" y=\"28\" width=\"70\" height=\"28\" fill=\"#60a5fa\"/><text x=\"170\" y=\"46\" fill=\"#141720\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">選ばれた学校</text><line x1=\"205\" y1=\"42\" x2=\"233\" y2=\"42\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><polygon points=\"237,42 231,38.5 231,45.5\" fill=\"#8892a4\"/><rect x=\"240\" y=\"28\" width=\"80\" height=\"28\" fill=\"#c9a04a\"/><text x=\"280\" y=\"46\" fill=\"#141720\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">選ばれた生徒</text><text x=\"60\" y=\"72\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">1段目：市区町村を選ぶ</text><text x=\"170\" y=\"72\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">2段目：学校を選ぶ</text><text x=\"280\" y=\"72\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">3段目：生徒を選ぶ</text><text x=\"170\" y=\"100\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">段階を踏むたびに、範囲がどんどん狭くなる</text><text x=\"170\" y=\"116\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">クラスター抽出法(1段だけ)と違い、複数段を経る</text></svg>", "terms": [["段(ステージ)", "多段抽出法で範囲を絞り込む1回分の手順。ここでは市区町村→学校→生徒の3段"], ["多段抽出法", "大きい単位から小さい単位へ、段階的に抽出範囲を絞り込んでいく方法"]], "think": "なぜ1回で生徒を直接選ばず、段階を踏むのかがカギ。全国の中学生から直接生徒を無作為に選ぶと、選ばれた生徒が全国のあちこちに散らばってしまい、訪問や調査の手間がクラスター抽出法の課題と同じように膨らむ。市区町村→学校と大きい単位から順に絞り込んでいけば、最終的に訪問する場所は絞られた学校だけで済み、手間を抑えながらも、1段階だけのクラスター抽出法よりもさらに細かく標本の範囲を調整できる。", "vs": "クラスター抽出法は「塊を選んで、その中は丸ごと全部調べる」という1段階の絞り込みで終わるのに対し、多段抽出法は「選んだ範囲の中を、さらにもう一段選ぶ」を繰り返す点が違う。段階の数が1つか複数かが見分け方になる。", "why_asked": "国勢調査以外の大規模な公的統計調査の多くは、実務上この多段抽出法に近い設計で行われている。層化・クラスター・系統というここまでの各手法は、多段抽出法の中のどこかの段階で組み合わせて使われることも多い。", "usecase": "全国学力調査、大規模な世帯調査、健康調査など、対象が全国に広がっていて、かつ段階ごとに扱いやすい単位(都道府県→市区町村→世帯のような)がある調査で使われる。", "opt": ["正解。市区町村→学校→生徒と、大きい単位から小さい単位へ段階を踏んで絞り込んでいるので多段抽出法にあたる。", "クラスター抽出法は塊を選んだらその中を丸ごと調べる、1段階で完結する方法。今回は学校を選んだあとさらに生徒を選ぶ段階があるため、1段階では終わっていない。", "層化抽出法はあらかじめ性質の近い層に分けてから各層で無作為に選ぶ方法。今回は大きい単位から順に絞り込んでおり、層に分けているわけではない。", "系統抽出法は名簿に等間隔で番号を振って一定間隔で選ぶ方法。今回は市区町村・学校・生徒という単位を段階的に絞り込んでおり、等間隔の抽出ではない。"]}'),

  ('stats17-q08', '標本調査法',
   '層化抽出法で選ばれた300人に調査票を送ったが、実際に回答してくれたのは180人だけだった。この180人だけを集計すると、母集団全体の実態とズレてしまうことがある。このズレの原因になりうる現象を何と呼ぶ？',
   NULL::text,
   '["セレクションバイアス（回答した人だけに偏ることで、結果が母集団の実態とズレる状態）", "疑似相関（交絡とは別に、直接の関係がない2つの出来事が、たまたま同時に起きて見えるだけの関係）", "交絡（結果と原因の両方に影響している、隠れた第3の要因があるという状態）", "標準誤差（標本から求めた平均などの推定値が、調査のたびにどれくらいばらつくかを表す大きさ）"]',
   0, '[0]', 'single',
   '{"asked": "選ばれた300人のうち回答した180人だけを集計すると、なぜ母集団の実態とズレることがあるのか、その現象の名前。", "point": "正しく無作為に選んでも、答えてくれた人だけを見れば、それは「回答するかどうか」でもう一度選ばれ直した、別の偏った集団になっている。", "kid": "300人を選ぶところまでは公平にできても、そのうち答えてくれた180人が、たとえば時間に余裕がある人や、その話題に関心が強い人に偏っていることがある。すると180人だけの集計は、母集団全体の実態とはズレてしまう。", "eg": "以前学んだ、生き残った戦闘機の弾痕だけを見て補強場所を考えてしまう話と同じ構造。あのときは『生き残れた機体』だけが見えていたことが偏りの原因だった。今回は『回答してくれた人』だけが見えていることが、同じ種類の偏りを生む。", "viz": "<svg viewBox=\"0 0 340 136\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">選ばれた300人のうち、答えたのは180人だけ</text><rect x=\"30\" y=\"28\" width=\"280\" height=\"40\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"30\" y=\"28\" width=\"168\" height=\"40\" fill=\"#3b82f6\"/><rect x=\"198\" y=\"28\" width=\"112\" height=\"40\" fill=\"#2a2f3f\" opacity=\"0.5\"/><text x=\"114\" y=\"52\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">回答した180人</text><text x=\"254\" y=\"52\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">未回答120人</text><line x1=\"198\" y1=\"22\" x2=\"198\" y2=\"74\" stroke=\"#c9a04a\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\"/><text x=\"170\" y=\"90\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">集計に使えるのは、青い180人だけ</text><text x=\"170\" y=\"108\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">回答する・しないにも偏りがあるなら</text><text x=\"170\" y=\"122\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">180人は母集団の縮図とは言えなくなる</text></svg>", "terms": [["無回答バイアス", "調査対象に選ばれても回答しない人がいることで生じる偏り。セレクションバイアスの一種"], ["セレクションバイアス", "対象の選ばれ方に偏りがあるせいで、データ全体が実態とずれてしまう状態。既に学んだ用語"]], "think": "なぜ抽出の段階が公平でも偏りが残るのかがカギ。層化抽出法で300人を選ぶところまでは、たしかに母集団の縮図になるように工夫されている。しかしその後、実際に回答するかどうかは対象者本人の判断にゆだねられていて、調査する側はコントロールできない。もし『時間に余裕がある人』や『その話題に関心が強い人』ほど回答しやすいという偏りがあるなら、回答した180人はもう一度、別の基準で選ばれ直した集団になってしまう。せっかく公平に選んだ300人の意味が、回答段階の偏りで薄れてしまう。", "vs": "以前学んだ交絡や疑似相関は『2つの出来事の関係の読み方』についての注意点だった。セレクションバイアスは『そもそも見ているデータの集まり方』についての注意点で、関係を読む前の、もっと手前の段階の問題。", "why_asked": "標本設計(層化・クラスター・系統・多段)をどれだけ工夫しても、回答してくれた人だけに偏りがあると、その工夫の効果が失われてしまう。抽出の工夫と回収後のチェックは、どちらも欠かせないという実務上の注意点として押さえておく。", "usecase": "アンケートや世論調査の結果を見るとき、回収率(送った数のうち何%が実際に回答したか)を確認し、回答者と未回答者で属性に偏りがないかを調べることで、この種のズレをある程度チェックできる。", "opt": ["正解。回答してくれた人だけに偏ることで集計結果が母集団の実態とズレる現象なので、セレクションバイアスにあたる。", "疑似相関は、直接の関係がない2つの出来事がたまたま同時に起きて見えるだけの関係。今回は回答の偏り自体が問題で、2つの出来事の見かけの関係の話ではない。", "交絡は、結果と原因の両方に影響する隠れた第3の要因がある状態。今回は『回答するかどうか』という選ばれ方自体の偏りが問題で、交絡とは別の種類のズレ。", "標準誤差は、標本から求めた推定値が調査のたびにどれくらいばらつくかを表す大きさ。今回問題にしているのは偏り(かたより)であって、ばらつきの大きさそのものではない。"]}'),

  ('stats17-q09', '標本調査法',
   'ある自治体は、調査結果の標準誤差を今の±6%から±3%まで小さくしたい。今の標本の大きさが400人だとすると、必要な標本の大きさはおよそ何人か。標準誤差は標本の大きさの平方根に反比例する。',
   NULL::text,
   '["1600人", "800人", "200人", "400人のままでよい"]',
   0, '[0]', 'single',
   '{"asked": "標準誤差を半分にするために必要な、標本の大きさの計算。", "point": "標準誤差を半分にしたいなら、標本の大きさは4倍にする。誤差を小さくするほど、必要な人数は誤差の縮小分よりずっと大きく増える。", "kid": "標準誤差は「√n(標本の大きさの平方根)」の逆数に比例して小さくなる。だから誤差を半分にしたいなら、標本の大きさは2倍ではなく4倍にしないといけない。", "eg": "以前、100人の標本で誤差±4%だったものを、半分の±2%にするには400人(4倍)必要だと学んだ。今回はそのときと同じ関係を、6%→3%という別の数字で確認する。", "calc": "今の標本  n=400人、標準誤差=±6%\n誤差を半分(±3%)にしたい\n\n標準誤差は「1/√n」に比例する\n→ 誤差を半分にするには、√nを2倍にする必要がある\n→ √nを2倍にするには、nを2×2=4倍にする必要がある\n\n400人 × 4 = 1600人", "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">誤差を半分にするには、標本を4倍にする</text><text x=\"90\" y=\"36\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">今の標本 400人</text><rect x=\"50\" y=\"44\" width=\"80\" height=\"24\" fill=\"#3b82f6\"/><text x=\"90\" y=\"60\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"700\">誤差±6%</text><line x1=\"140\" y1=\"56\" x2=\"168\" y2=\"56\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><polygon points=\"172,56 166,52.5 166,59.5\" fill=\"#8892a4\"/><text x=\"250\" y=\"36\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">必要な標本 1600人</text><rect x=\"180\" y=\"44\" width=\"140\" height=\"24\" fill=\"#60a5fa\"/><text x=\"250\" y=\"60\" fill=\"#141720\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"700\">誤差±3%</text><text x=\"170\" y=\"92\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">誤差は1/√nに比例するので、誤差を半分にするには</text><text x=\"170\" y=\"106\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">標本を2倍ではなく4倍にする必要がある</text><text x=\"170\" y=\"124\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">400×4=1600人</text></svg>", "terms": [["標準誤差", "標本から求めた推定値が、調査のたびにどれくらいばらつくかを表す大きさ。既に学んだ用語"], ["標本の大きさ(サンプルサイズ)", "調査で実際に選ぶ対象の人数"]], "think": "なぜ誤差を半分にするのに、人数は2倍ではなく4倍必要になるのかがカギ。標準誤差は標本の大きさnの平方根の逆数、つまり1/√nに比例して小さくなる。誤差を半分にしたいなら、1/√nの値を半分にする必要があり、そのためには√nを2倍にしなければならない。そして√nを2倍にするには、nそのものは2を2乗した4倍にする必要がある(√(4n)=2×√n)。平方根という関係のせいで、誤差の縮小幅よりも必要な人数の増え方のほうが大きくなる。", "vs": "「誤差を半分にしたいなら人数も半分でよい」あるいは「2倍でよい」という直感は誤り。標本の大きさと誤差は比例ではなく、平方根の関係でつながっている点が、単純な比例の関係とは違う。", "why_asked": "標本の大きさは、ただ多ければ多いほどよいわけではなく、どこまで誤差を許容できるかという目標と、それを達成するための人数の増え方(平方根の関係で急に増える)、そして人数を増やすほどかさむ調査のコストとのバランスで決める。この計算ができないと、必要な標本の大きさを見積もれない。", "usecase": "世論調査や品質検査で「誤差を±3%以内に収めたい」のように目標を決めたうえで、それに必要な標本の大きさを事前に見積もる場面で使う。層化抽出やクラスター抽出でどう対象を選ぶかを決めたあとも、最終的に何人分のデータを集めるかは、この誤差との関係で決まる。", "opt": ["正解。標準誤差は1/√nに比例するので、誤差を半分にするには√nを2倍、つまりnを4倍にする必要がある。400人×4=1600人。", "誤差と人数を単純に比例させて2倍とした誤り。実際には平方根の関係があるため、誤差を半分にするには人数を4倍にする必要がある。", "人数を減らすと誤差はかえって大きくなる。200人は今の400人よりも少ないので、誤差を小さくするどころか大きくしてしまう方向。", "誤差を小さくしたいという目標があるので、今の400人のままでは足りない。標本の大きさを変えずに誤差だけを小さくすることはできない。"]}'),

  ('stats17-q10', '標本調査法',
   '国勢調査は日本に住む人全員を対象にする全数調査だが、多くの大規模な世論調査や統計調査では、単純無作為抽出だけでなく、層化抽出法・クラスター抽出法・系統抽出法・多段抽出法を組み合わせて実施することが多い。このように複数の抽出法を組み合わせる最大の理由は何か？',
   NULL::text,
   '["単純無作為抽出だけではコストがかさみ構造も反映しづらいため、長所を組み合わせて弱点を補う", "複数の抽出法を組み合わせると標本誤差が完全にゼロになるため、信頼区間を計算する必要がなくなる", "統計調査には必ず4種類すべての抽出法を使うことが法律で義務づけられているため", "抽出法を複数組み合わせるほど、回答してくれる人の割合(回収率)が自動的に上がるため"]',
   0, '[0]', 'single',
   '{"asked": "実際の統計調査で、複数の抽出法をわざわざ組み合わせて使う理由。", "point": "1つの抽出法だけでは「コストは低いが精度が心配」「精度は高いが手間が大きい」のような一長一短がある。段階ごとに得意な方法を組み合わせることで、弱点を補い合う。", "kid": "ここまで学んだ層化抽出法・クラスター抽出法・系統抽出法・多段抽出法は、それぞれ得意なことと苦手なことが違う。実際の大規模な調査では、1つだけを使うのではなく、いいとこ取りをするように何段階かで組み合わせて使うことが多い。", "eg": "旅行の計画に近い。飛行機だけ、電車だけ、徒歩だけで目的地まですべてをまかなおうとせず、長距離は飛行機、街の中は電車、最後の数百メートルは徒歩というように、それぞれ得意な区間で乗り物を使い分ける。統計調査の抽出法も同じように使い分ける。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">段階ごとに得意な抽出法を組み合わせる例</text><rect x=\"20\" y=\"28\" width=\"90\" height=\"30\" fill=\"#3b82f6\"/><text x=\"65\" y=\"44\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">全国から地区を</text><text x=\"65\" y=\"55\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">クラスター抽出</text><line x1=\"110\" y1=\"43\" x2=\"128\" y2=\"43\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><polygon points=\"132,43 126,39.5 126,46.5\" fill=\"#8892a4\"/><rect x=\"135\" y=\"28\" width=\"90\" height=\"30\" fill=\"#60a5fa\"/><text x=\"180\" y=\"44\" fill=\"#141720\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">地区内で世帯を</text><text x=\"180\" y=\"55\" fill=\"#141720\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">系統抽出</text><line x1=\"225\" y1=\"43\" x2=\"243\" y2=\"43\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><polygon points=\"247,43 241,39.5 241,46.5\" fill=\"#8892a4\"/><rect x=\"250\" y=\"28\" width=\"70\" height=\"30\" fill=\"#c9a04a\"/><text x=\"285\" y=\"44\" fill=\"#141720\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">年代で層化</text><text x=\"285\" y=\"55\" fill=\"#141720\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">して選ぶ</text><text x=\"170\" y=\"80\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">クラスターで訪問の手間を抑え、系統抽出で機械的に選び</text><text x=\"170\" y=\"94\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">層化で年代の取りこぼしを防ぐ、というように役割分担する</text><text x=\"170\" y=\"118\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">1つの方法だけでは補えない弱点を、組み合わせで補う</text><text x=\"170\" y=\"134\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">(実際の設計は調査ごとに異なる。上の組み合わせは一例)</text></svg>", "terms": [["全数調査", "母集団の全員を対象に調べる方法。国勢調査が代表例。既に学んだ用語"], ["標本設計", "どの抽出法をどう組み合わせて標本を選ぶか、調査全体の計画を決めること"]], "think": "なぜ1つの抽出法だけで済ませないのかがカギ。単純無作為抽出は理論上もっとも公平だが、対象が全国規模だと訪問の手間やコストが膨大になる(Q1)。クラスター抽出法はその手間を抑えられるが、選ばれた塊がたまたま特徴の偏った地区だと、全体としての精度が落ちる心配が残る。層化抽出法を組み合わせて年代などの層ごとの取りこぼしを防ぎ、系統抽出法で名簿からの選び方を手軽に済ませる、というように、それぞれの方法の得意なところだけを段階ごとに使うことで、コストと精度のバランスを取っている。", "vs": "「複数の方法を組み合わせる=より複雑で優れた方法」という話ではなく、「1つの方法だけでは残ってしまう弱点を、別の方法の得意なところで補う」という役割分担の発想。どの組み合わせが最適かは、調査の目的や対象によって毎回変わる。", "why_asked": "ここまで学んだ層化・クラスター・系統・多段の各抽出法は、単独の知識としてだけでなく、実際の統計調査ではどう組み合わされているかまで理解して、初めて実務での標本設計の判断につながる。", "usecase": "国が行う大規模な世帯調査や労働力調査、大手メディアの世論調査など、全国規模でありながら一定の精度も求められる調査の設計で、この組み合わせの発想が使われている。", "opt": ["正解。単純無作為抽出だけではコストや母集団の構造への対応に限界があるため、層化・クラスター・系統・多段などを段階ごとに組み合わせて弱点を補い合っている。", "抽出法を組み合わせても標本誤差がゼロになるわけではない。標本調査である以上、誤差や信頼区間という考え方は組み合わせたあとも必要であり続ける。", "4種類すべてを必ず使うことが法律で義務づけられているという事実はなく、調査の目的や対象に応じてどの方法をどう組み合わせるかを設計する。", "抽出法の組み合わせは選び方の工夫であり、選ばれた人が実際に回答してくれるかどうか(回収率)を自動的に上げる仕組みではない。回収率は別に対策が必要な問題として既に学んだ。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'stats-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
